(()=>{const W=DriveWorld,S=DriveSimulation,wrap=document.querySelector('.scene-wrap');let dest=null,path=[],lastState,elapsed=0;const toggle=document.createElement('button');toggle.className='nav-toggle';toggle.type='button';toggle.textContent='⌖  Navigator';toggle.setAttribute('aria-expanded','false');wrap.append(toggle);const panel=document.createElement('div');panel.className='nav-panel';panel.id='navigator-destinations';panel.hidden=true;toggle.setAttribute('aria-controls',panel.id);wrap.append(panel);const title=document.createElement('strong');title.textContent='Alege destinația';panel.append(title);const instruction=document.createElement('div');instruction.className='nav-instruction';instruction.hidden=true;instruction.setAttribute('role','status');wrap.append(instruction);function open(value){panel.hidden=!value;toggle.setAttribute('aria-expanded',String(value));}toggle.onclick=()=>open(panel.hidden);
function nearest(p){return W.junctions.reduce((a,b)=>Math.hypot(b.x-p.x,b.z-p.z)<Math.hypot(a.x-p.x,a.z-p.z)?b:a);}
function bfs(start,end){const q=[start],prev=new Map([[start.id,null]]);while(q.length){const n=q.shift();if(n===end)break;for(let d=0;d<4;d++){const next=W.neighbor(n,d);if(next&&!prev.has(next.id)){prev.set(next.id,n);q.push(next);}}}if(!prev.has(end.id))return[];const nodes=[];for(let n=end;n;n=prev.get(n.id))nodes.unshift(n);return nodes;}
function route(p,d){const end=nearest(d);const candidates=W.junctions.filter(n=>Math.abs(n.x-p.x)<1.8||Math.abs(n.z-p.z)<1.8).sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z)).slice(0,4);if(!candidates.length)candidates.push(nearest(p));let best=[],cost=Infinity;for(const n of candidates){const nodes=bfs(n,end);if(!nodes.length)continue;const angle=Math.atan2(n.z-p.z,n.x-p.x)-p.angle,behind=Math.cos(angle)<-.3;const c=Math.hypot(n.x-p.x,n.z-p.z)+(nodes.length-1)*16+(behind?25:0);if(c<cost){cost=c;best=nodes;}}return best;}
function select(p){dest=p;path=lastState?route(lastState.player,p):[];elapsed=0;open(false);toggle.classList.add('is-active');}
for(const p of [...W.services,...W.landmarks]){const b=document.createElement('button');b.type='button';b.textContent=p.name;b.onclick=()=>select(p);panel.append(b);}const stop=document.createElement('button');stop.textContent='Oprește navigația';stop.className='nav-stop';stop.onclick=()=>{dest=null;path=[];instruction.hidden=true;toggle.classList.remove('is-active');open(false);};panel.append(stop);document.addEventListener('keydown',e=>{if(e.key==='Escape')open(false);});
const meters=d=>Math.max(10,Math.round(d*6/10)*10);function direction(delta){return Math.abs(delta)>2.4?'↶ Întoarce când este permis':delta>.55?'↱ Dreapta':delta<-.55?'↰ Stânga':'↑ Înainte';}
const update=S.update;S.update=(s,input,dt)=>{update(s,input,dt);lastState=s;if(!dest)return;const p=s.player,distance=Math.hypot(dest.x-p.x,dest.z-p.z);instruction.hidden=false;if(distance<2.7){instruction.textContent='✓ Ai ajuns · '+dest.name;path=[];return;}elapsed+=dt;if(!path.length){path=route(p,dest);elapsed=0;}while(path.length&&Math.hypot(path[0].x-p.x,path[0].z-p.z)<2.4)path.shift();if(elapsed>4&&path.length&&Math.hypot(path[0].x-p.x,path[0].z-p.z)>19){path=route(p,dest);elapsed=0;}
const next=path[0]||dest,dx=next.x-p.x,dz=next.z-p.z,dist=Math.hypot(dx,dz),a=Math.atan2(dz,dx);let delta=Math.atan2(Math.sin(a-p.angle),Math.cos(a-p.angle));let caption=direction(delta);if(Math.abs(delta)<.55&&path.length>1){const after=path[1],turn=Math.atan2(after.z-next.z,after.x-next.x)-a;caption=direction(Math.atan2(Math.sin(turn),Math.cos(turn)));}instruction.textContent=caption+' · '+meters(dist)+' m · '+dest.name;};
window.DriveNavigator={path:()=>dest?path:[],destination:()=>dest,route};})();
